) AS (
  VALUES 
    (534::BIGINT, 'Para llevar Lab con el hay que tener en cuenta varios aspectos... -Quiz todas las semanas al empezar -Ponganle nombre a Todos los cuadros -Explica MUY rapido -Tiene un tono bastante golpeado pero normalmente no dice las cosas tan en serio, no se tomen nada personal.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, '8f86e6440125a74a5dbc490ea1837445e63dc5e183b4ef4c3b06d61e35c825bd'::TEXT, ARRAY[567]::BIGINT[]),
    (534::BIGINT, 'Si matricula con este profesor, tiene que tomar en cuenta varios aspectos. Tiene un tono muy golpeado, algo muy importante por hacer es no tomarte nada personal, simplemente quiere "romper el hielo" y ser un poco inspiracional pero explica tan rápido que uno se pierde y si pides ayuda, te habla feo.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2026-02-20T00:00:00+00:00'::TIMESTAMPTZ, 'aa125a5033ec692ce80e18f3f8241e99df8694d745ed18612e6fbb79db146cd2'::TEXT, ARRAY[567]::BIGINT[]),
    (534::BIGINT, 'habla golpeado, los quizes son faciles, marco teorico, a veces procedimiento, no es mal profe pero su manera de referirse a los estudiantes no es la ideal, es todo concho si matricula con el, trate de pasar desapercibido para que no lo joda'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'c1d027839bbcc0e03f1ebb69b07de1288adb0db1990f8c541bbef5ae3f3d5978'::TEXT, ARRAY[613]::BIGINT[]),
    (534::BIGINT, 'Su tono de voz es bastante fuerte y parece que habla enojado, califica suave los informes y parciales, sus quizzes son marco teórico, cuestionario previo y a veces procedimiento, tiene un humor algo random'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'e1556b2cd6f1f82eaa4b3333e5656ae0d8250ee6dab4d835803d13e74ff77ad9'::TEXT, ARRAY[613]::BIGINT[]),
    (534::BIGINT, 'Es grosero, bastante, pero algo cómico, da una explicación al inicio bastante clara, los quizzes son básicamente, marco teórico, cuestionario previo y procedimiento.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '3bdf1569ec897c6ed72a1b4d7031792b2ea6289b18f0de10ad40ac41f4de169f'::TEXT, ARRAY[613]::BIGINT[]),
    (534::BIGINT, 'El profe digamos que es... Curioso No diría que es mal profesor, es grosero pero con todo mundo y no es nada personal, es saber llevarle su juego. En los informes sí ayuda mucho sus explicaciones al inicio de clase ya que básicamente te responde casi todas las preguntas.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'e2ef4aba90dd004a612bba2147d7bdd37ce267ae111adf4ab0f78b78c271a15f'::TEXT, ARRAY[613]::BIGINT[]),
    (534::BIGINT, 'Es una excelente persona pero a la hora de explicar algún tema no se le entiende nada no sé si sea por su voz o por qué se desvía mucho y al final no explico nada. Con el no se pueden hacer apuntes ya que es muy desordenado a la hora de explicar.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'caf0dd1d55c7730b4c7d9a038e85fa739d03ea0cf12c7d97f471bf9f438ba46d'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Eso que dicen es totalmente cierto, si le pregunta una vez le va a seguir preguntando todo el semestre. Tampoco siento que sea mal profesor, solo sus clases son aburridas pero se nota que sabe mucho'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases largas']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'd9926f12eadb6ee652184ec8c1673b71933d012f97ea1c56cb6f4223c8ed7d72'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases largas']::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, '9ee94528d1110b5c09f9f90ff2e97e67d0c970f6472a3bf2fc71050546f392f0'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'es muy bueno en química, se enreda enreda algunas veces al explicar, hace muchos quices lo que ayuda a subir el ponderado, si le pregunta 1 ves y usted responde, le va a preguntar todo el semestre, pero esto lo obliga a prestar atención y es muy grosero al hablar'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'b5b9d5d076a564af9cc0ddf51c45effdd4e5d96303c04598c6cb7ceec18ef94c'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Tienen que estar sobre la jugada, porque si no se quedan en el curso. Además, si el profe le pregunta una vez y usted le responde, probablemente le siga preguntando durante todo el semestre, tiene una mala vocalización, pero si se disfruta en clases con las bromas que hace.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2021-06-18T00:00:00+00:00'::TIMESTAMPTZ, '30b89bbbaa0e4385811c886842f022ecbf9eb67a2f59e3637a284252bb925aae'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Prepárese para que le pregunte a cada rato en la clase, hace quices toda las semanaspara subir el ponderado, pero trata mal a sus estudiantes diciendo "put4 más necio". Sus apuntes para explicar no se entienden nada. Si lo lleva con él trate de llevar éxito académico con un buen tutor.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '9fd4dde442a8f8b5a205d179a4c3842bddacfeb5780d7da87d867358b3018726'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (534::BIGINT, 'Es un muy buen profesor, tiene su cierto humor, lo que hace que la clase no sea aburrida, pero prepárese por si le pregunta, porque cuando lo hace una vez, lo hace todo el semestre. Explica super bien, solo que a veces se enreda. El mae dice "Gracioso" en vez de gaseoso :v intenta ser tuanis JAJJA'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Da crédito extra']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '33de9fc3a63cfaa1284bc10e8ce1f4f8341ab92ef62901ba16eec6badc03627a'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Definitivamente no lo recomiendo si quieres entender la materia, hace presentaciones que no explica, cuando ve un tema nuevo deja toda la materia de lado y pasa directamente a la práctica, comienza a resolver ejercicios y uno no sabe ni por qué hace lo que hace. Se aprende más en las tutorías...'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-07T00:00:00+00:00'::TIMESTAMPTZ, 'f3da470bfe1342d38c6111d8257fd3020b8e3c2352b21973d0624c0733ce7195'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Si no es autodidacta busque ayuda y tutorías porque el profesor, a pesar de saber mucho, no sabe explicar. Atiende el teléfono durante clase, explica de manera muy confusa, dice malas palabras y gime en clase.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'b56805c341d3a9d8746e0d88093dfa148b7de418d8e6424bca9c8b6edc71ef29'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Compromete a participar en clases, trata de hacer su trabajo bien, pero explica como si todos tuviesemos el mismo nivel de conocimiento que el.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '890b46d96b387f17d67ef45c4b28a9233b51be83b524f6348ad797d9c43e8872'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Es el primer profe que conozco que le habla a los alumnos de "mamón", "picha", "idiota"... Sumamente malo en el manejo de la materia (hay hasta que ayudarle a explicar). Llevan con él porque si sos "compa" te regala pts al final para pasar. ¡Vergüenza, descaro y alcagüetería que sea profe del Tec!'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'cb05f2f92e76f9ecfbb5b0a5ea306e1524537b287f558507e19add377c66e042'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (534::BIGINT, 'Es vacilon el profe pero a su modo, se preocupa mucho por que uno pase, hace muchos quices y al final elimina 2 de los mas malos, da muchas oportunidades para realizar las autoevaluaciones, es muy accesible. Si se recomienda llevar con el'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '2157b9ae5641b4d684f73ef42b8e963b5a156d48854027ec494824d2f102a1af'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Las clases son un toque desordenadas, importa la participación, hace chistes y le gusta que uno prenda el micrófono y se ria. Si usted no tiene buenas bases y va a éxito académico la tarea se saca a flote. Hace muchos quices para a final de semestre cancelar las notas más bajas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'a5f3d4266b35124ef725c2e867daffeedecd66f39845b58f1d035b54f110769f'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Si tenés buenas bases de química curiosamente este profe es una buena opción. El mae ayuda y se preocupa por que uno pase, pero se enreda explicando. Tiene un sentido del humor rarísimo, si a vos te mosquea eso, no matriculés con él.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'bdd8ccea200b110d1a4f14d21523626bd2189cb34a363859230ba9f5fbd6a036'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Al principio parece muy grosero y burlista pero solo es así si no prestan atención. Las clases son claras y divertidas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'cde10873f409385c6e4954f3ce5cc637484e5bdc6c48c0bf67da7fb79d250512'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Entenderle en un principio cuesta, y no es el más diestro en tecnología. Pero le pone mucho ahínco y se preocupa por los estudiantes. No tiene hora de consulta propiamente dicho, pero si usted le escribe por whatsapp o Teams a la hora que le da a principio de semestre, le va ayudar.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '54d46ede1bfb83f0fe6187cabad9d640a5d99248b4a332f2ab745e6b0a508984'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Si matricula con él le recomiendo que busque un amigo con otro profesor y le pida los vídeos de las clases y los apuntes. Él tiene muchos errores al calificar y no se entiende muy bien. No sube la nota correcta en el TEC Digital y si le preguntas algo por mensaje, te deja en visto. Igual asista'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, '5c932b894e5d23ca315b252eb9d3bec901f9fd156fdd8bc7169856b788c4a46e'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-03T00:00:00+00:00'::TIMESTAMPTZ, '4ae470cbfead3ed8fbc55d679ff173549c96b32f34d62b25a95e422a6163dd4a'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'si matricula con él se va a reír toda la clase, al principio cuesta un poco entenderlo, pero después usted entiende todo súper fácil, un consejo es que participe porque así va a entender y el profe lo valora. Al profe le interesa demasiado que usted entienda.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'f8b9c7af12285afbe08ad0db022b4a96419eac2fc431d37a9e205f3028369c72'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Explica muy bien, hace las clases divertidas y el tiempo se pasa rápido. Hace bromas entonces si no le gusta el sarcasmo mejor matricule con otro. Hace quices todas las semanas por lo que es fácil mantenerse al día para el examen. Muy recomendado!!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2020-05-21T00:00:00+00:00'::TIMESTAMPTZ, '95b530993f50e40784de42412398fc9f44a08f9b8eb29baf300253d55e6a45ea'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'es un profe que da muchas vueltas en un mismo tema y se enreda muchísimo ademas es muy confuso, no acepta las dudas o cuestionamientos a sus explicaciones o respuestas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Pocos exámenes']::TEXT[], '2020-04-30T00:00:00+00:00'::TIMESTAMPTZ, 'f9e4070ab20f492feb1a363eabd96a0a5923f0d2ac9a73b6334016848829f539'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (534::BIGINT, 'Es muy desordenado para explicar y eso acompañado de su mala vocalización hace que sea difícil entenderle, es muy buena persona y lo ayuda si no necesita, solo hay que ser un poco autodidacta, los quices se los califica uno mismo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Da crédito extra']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '540c3e008317a5f13d96534befe0e64015c2e500faef8729484dbc4cd1348433'::TEXT, ARRAY[614]::BIGINT[]),
    (534::BIGINT, 'Es un exelente profesor, las clases se sobre llevan gracias al caracter de él. Da muchos tips que sirven mucho para los examenes y hace quices iguales al examen. Es bromista, si usted no le gusta que le corrijan mejor no matricule con él.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '59c7e9ee9e51f3cf69bd091cdf7384b4f4396e13052d5e5afc987b9bdb958b72'::TEXT, ARRAY[614]::BIGINT[]),
    (534::BIGINT, 'El profe es muy bueno, tiene una manera particular de ser por lo que no a todos les cae bien pero si te ve participativo e interesado en la clase le caerás bien. Siempre recuerda quien no va a sus clases, explica claro y directo, lo que se necesita para los exámenes. Suele hacer muchos quices.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-16T00:00:00+00:00'::TIMESTAMPTZ, '299d5915821cf29e188e6319ba929bd00f6bff86f290c0455bf9f673bfb53f91'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Recomendado. Excelente profesor. He de decir que al inicio caerá mal porque es muy brusco y parece que humilla. Sin embargo, el profesor es cercano a los estudiantes y siempre sabe quienes van a sus clases. Además, explica todo como se debe sin rodeos ni nada por el estilo. Curso fácil si se estudia'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-15T00:00:00+00:00'::TIMESTAMPTZ, '198833c37692e6497bad145d40b5124c1364e2ebb826d31892af218092585816'::TEXT, ARRAY[614]::BIGINT[]),
    (534::BIGINT, 'No a todos les cae bien, hay que saberlo llevar, los quices son fáciles pero sí hay que estudiar mucho individualmente para los parciales, al menos la cátedra de química 1 está muy ordenada y clara por lo que estudiar solo no es difícil'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-12T00:00:00+00:00'::TIMESTAMPTZ, '0fe4964379fcf75514a1c30b96377f9e2525a0c4c809c34b784c418c10e10f12'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'El profe es un toque confuso y no lo recomiendo mucho. La materia se tiene que aprender a punta de ejercicios en la casa. Sin embargo, los quices los califica uno así que ese porcentaje está garantizado.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-11T00:00:00+00:00'::TIMESTAMPTZ, '3b87f710611ceb1829bf12077786e4f9e281a5be453f926da3043654f00ed828'::TEXT, ARRAY[614]::BIGINT[]),
    (534::BIGINT, 'Deja muchos quices que uno mismo revisa. El profe explica muy bien los temas, aunque aveces vuelve de un punto a otro provocando confusión. La clase es vacilona aunque aveces puede pasarse fichando gente que se duerme en la clase, o que pregunta mucho, etc, entonces trate de que te fiche bien.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-22T00:00:00+00:00'::TIMESTAMPTZ, '96e260917474d14e6aa2596e164ab487394e83b488e6ff5c36c1df2f98a36b48'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Es un cagón de risa pero no explica bien la materia. Solo vale la pena ir a los quices porque se autoevaluan y se tiene ese 25% asegurado. Tome la clase con él si sabe auto enseñarse la materia o tiene tutor. Y solo vale la pena ir a las clases cuando hay quiz, de lo contrario es perder el tiempo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1a0f40b47291d578744eb9cbbd79500a279b376c5c141b22d7caa95a9914313a'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Explica muy a su manera, las clases pueden llegar a ser un poco incómodas, pero es una buena persona. Para pasar hay que estudiar solo.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '68c16b40970e7f8c9505685f11317ca67ad6deb98d0a8d6d359f6a93fc7f89f3'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Hace muchos quizes asi que no ir no es opcion porque los pierde. Es raro, le da por gemir en media clase. El tacto con el estudiante es medio raro e incomodo. No explica mucho y se pierde solo, hasta balbucea. Hay presentaciones de la materia y eso ayuda'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '0657ca3fa6308682682635c23067da35eb1c1369aac69dd10843a30185ff2b8e'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'El profe es demasiado gracioso, pero muy malo con los estudiantes, a veces no se le entiende nada, pero cuando quiere explica bien'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ba902dbeae9d6e794426f54937821e88722cb19e507fd1c9cc88f3ad364469da'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'El profe es bastante rudo en su manera de expresarse hacia los estudiantes, hace unas analogías fuera del estadio. Hay ocasiones en las que no se le entiende una palabra de lo que dice, pero cuando explica bien, se luce.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '109d57e428284d6affe8784a0c796caaa3e2b4ff41c02a57c3a34ffdcac32988'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'El mae es buena nota, pero explica muy Confuso y gime en medio de la clase, para pasar se estudia solo, el mae no explica muy bien, los quinces se autoevaluan y gana un 25% fácil.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'e808e171d9c4337b738528059fc498601456bdaf14b947117e8fdcb23459d23c'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (534::BIGINT, 'El profe sabe bastante, el problema es que no sabe muy bien expresar sus ideas. Usted califica su propio quiz y hace bastantes. Es un poco descortés, pero se logra soportar.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'db64af8be12d173cdc8aa13166b93d239180de44734815bf88d17630c2fb8717'::TEXT, ARRAY[614]::BIGINT[]),
    (534::BIGINT, 'El mae sí sabe de lo que está hablando, pero la forma en como lo expresa o explica no es la mejor. Es buena nota y vacilón, pero como profe es un poco difícil de entenderle.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2018-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'aeca33c47dfbc3dc52b687015adef437f93ba8f2704dab19c296fbed00665f0a'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (534::BIGINT, 'No se le entiende nada cuando habla y solo hacer bromas, si no me hubiera puesto a estudiar bastante me va mal, simplemente no se le entiende nada con analogías sin sentido y hablando sin articular. Además si uno se equivoca se burla de uno, y aunque eso lo hace divertido, después solo aburre'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores', 'La participación importa']::TEXT[], '2018-07-01T00:00:00+00:00'::TIMESTAMPTZ, '6babc32db6b884ab08774788f7aa5a88666b9b8e610d22d4a17c9b07f519b48e'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '69cc73bf61c264a95b7e55597d79ef799d3058ea93993837f664069be7833890'::TEXT, ARRAY[4253]::BIGINT[]),
    (534::BIGINT, 'Hace muchos quizzes (algo positivo), es un cagón de risa pero no es muy bueno explicando'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '66532d96da86b75788ad420b34131489010f26084abf67ea78e993a8e5a87c88'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-04T00:00:00+00:00'::TIMESTAMPTZ, '5eb50351432b77c3654897bb8c550e72b72030a472a5e73b07b9d155f37ab52c'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Si quieren tener un profe vacilon que se vez en cuando tiene orgasmos en la clase este es el indicado!!'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2018-03-08T00:00:00+00:00'::TIMESTAMPTZ, 'aefc65dbc51adad4a43c8ef8bf5b8659384b58d6885377a27d4dc87b08e5421c'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Buena nota el profe, no es difícil, solo repase la materia antes de cada clase por si le pregunta algo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'ec800e424db63c92bd5aadcd62503235830fc804aef80be5ed7c999cab2e7e18'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (534::BIGINT, 'Muy buena nota pero algunas veces se monta jaja explica lo necesario y hace poca práctica en clase. Quiz todas las semanas pero usted se lo califica entonces se puede ayudar'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'b28cd9e1a841258214e75df3f45b0d68345d5500426bc23fb9a0144324ba8940'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (534::BIGINT, 'A veces cuesta entenderle, como profesor se preocupa por los estudiantes siempre y cuando usted sea un buen estudiante. Si usted se ofende o no tolera ciertas cosas como burlas, no lo recomendaría.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2017-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'de7196f8aa70049e1f6b7666014a73bdf76771c6d0b1a04e98000f4ca1286c86'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Con este profe se siente universitario, se burla de los estudiantes, sabe mucho, explica bien, no le gusta que hablen en clase, pasa muy ocupado, al final es muy buena nota. Con este profe usted tiene que entrar con una mentalidad de verdadero estudiante, cállese, estudie, tome apuntes y es regalado'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'e93c1dd39af840adca98a0d6a1f722277aba36d173073f53ab15fa202d211874'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Es un cagón de risa, pero mejor meter otro profe jeje, se burla de los estudiantes jaja'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '6859ba64badb2caeaf292cdb3a10d1fd1123a4968377d46e7cb2fd8401635957'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Es una teja de persona, explica lo necesario, aburrido en teoría porque utiliza diapositivas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'd43226eb8c5c919b342cef3bf4e9d99ed8d7cca2bee93744b9dcb1296aa61c3d'::TEXT, ARRAY[614]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muy cómico']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1bcf97f4a260bbc1b529d72125d588ee67aea8bfc5cfe61756b07cc3af007d93'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Al principio puede ser un poco incómodo acostumbrarse a su trato, pero; una vez que van pasando las clases eso pasa. Explica bien. Cada quien revisa su quiz.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '86a79d269db75dcb844cd6f0014a1bbb65d5a3810210bc58bc1ec2ef09589d57'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'En cuestiones teóricas se le entiende pero en lo prático hace mucho desorden. Si se considera sensible no lleve con él pues es muy grocero con sus estudiantes, sin embargo puede llegar a ser muy vacilón.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ae0b3c33321b88eca033cd980beb79796c94d37764c622a810bf70421da10d33'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'FATAL. El mae pasa hablando por telefeno, no se toma la clase al chile. Pasa vacilando y puede llegar a chocar con los estudiantes. Hay maes MIL veces mejor que este mae.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'a9a57a30a5e4dee552adf855199b33b9ef00573a5c0799569433a557560f956f'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Muy buena nota, se vacila mucho y las clases se hacen cortas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '3b7f111b4d4650515032133fdc44901ee27810c5205f483a1a52bed8992b30a9'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Es una payasa, uno pasa cagado de risa en la clase. A algunos se les caga pero hay que saberlo llevar, el mae es buena nota y uno puede vacilar con él y la vara. Pero a veces se hace mucho despiche explicando, hay que ponerle bastante atención porque sí da datos importantes. Uno autorevisa el quiz.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, '99ccbb671a6374402b0bbb47d46b5e1c697f21b6d143e4f14c12b6682c6a81d7'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'No recomendado'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'b73710ca67e90b0740e581bfe0e41e787a4554af854cd74a579efec60e68e364'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'El Mae es muy grosero o hp, si ud es sensible, no meta con él, si no le importa, el Mae ayuda un montón es un vacilón, uno no para de reírse a veces se lagunea un poco pero en general es buen profe.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'fb62a65f1968fa2fb338dd5ec1a6571cb501f9a7daf3867142ff71cd3f33b45e'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (534::BIGINT, 'humor negro, se burla de estudiantes pero ayuda mucho y explica bien solo es de llevarlo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '5208366447ed6a2837bf24ca9294882f6ada855c7ce0104ede62949b43fc30b9'::TEXT, ARRAY[614]::BIGINT[]),
    (534::BIGINT, 'Peor profesor que he tenido en mi vida, irrespetuoso, malcriado, no ayuda a los estudiantes y se burla de ellos, NUNCA METAN CON EL SE LOS ADVIERTO!'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-26T00:00:00+00:00'::TIMESTAMPTZ, 'da13905225c38188b7c2c58bc569a0ffadc12e4269662bdcd4bdc77dc53fae9a'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'para química I es muy fácil, ayuda mucho y es entretenido para química II, es muy dificil, se enreda y no explica nada bien, tras de todo se burla de la gente si responde mal'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd857276983da9caea64a144a08dcc813691d91bdea5775f14f8364cf5c2e4189'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (534::BIGINT, 'A veces se enreda pero hace muchos quizes que son iguales al examen entonces eso ayuda un montón'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9c668d4001d879b520ed22e1c8034f2e3502560c70277ce40f42b2169e7c5b29'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'No es un buen profesor, él sabe lo que hace pero no explica bien. A veces hace bromas muy pesadas y se burla de los estudiantes por no responder bien. No lo recomiendo para nada, se enreda mucho y a veces ni él sabe las respuestas, Si le toca con él mejor vaya a tutorarías desde el inicio.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-20T00:00:00+00:00'::TIMESTAMPTZ, '4411bbb66e6a38615411e724eb068c1c2adba4d9636b612226402212d6ba730b'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-20T00:00:00+00:00'::TIMESTAMPTZ, '4b099a783ad4ef2b838f021b5e96385e6e07dca3f93a631d4a05430c66507c62'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Es todo un personaje, quizes fáciles, sabe de la materia pero no es el mejor explicando. Las clases no son aburridas ya que es bastante cómico, si usted es mujer( y peor si es macha) y matricula con él, sepa que desde la 1era clase la va a marcar'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2016-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'abde2d38bf70af76706a825372ab99c44803497c919e6e1627a1aa873ac8f0db'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, '09f97b30d5666ef53a5120ebe210a2692122ae8d7083d7b46a3abd369b68d83b'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '75540cf51441ff11b3db7d0c27b99cdbd1248ef8f8fc5b6d204de9d8d8d61911'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Las clases se hacen largas, no trata de la mejor manera a los estudiantes, todos son machos para el, se equivoca, algunas cosas las enseña mal, muchos quices lo cual no es malo, poca ayuda a la hora de dudas'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2016-05-25T00:00:00+00:00'::TIMESTAMPTZ, '95a38e4b876d017919f13de25e5fa8cba39a0c63878b17796b88be5752cc7feb'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Mucho vacilón y al final nada de nada. Si a usted no tiene tanta facilidad en la materia, va a tener que buscar a alguien que le explique. Hace muchos quizes, lo cual es bueno. No trata a los estudiantes de la mejor manera y si le pregunta algo, prepárese para el hachazo.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-14T00:00:00+00:00'::TIMESTAMPTZ, 'c56a0499b5a62cf0f81a3251a86f035c272b8a584bb6f85c4d3b2a42a4a0cf49'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, '¡Macho, macho! si quiere aprender, meta con otro profe, si quiere cagarse de risa y confundir la materia meta con el macho Juanca. A la vieja escuela, es fácil pasar solo es de estudiar aparte, ir de oyente a otro profe, etc. pero sus clases tampoco es que son un barco.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2016-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'ee2f6475014aec80e742641df438ee04896fbaa1ebac562b1a5bbef4a2491e41'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Se enreda mucho, y a veces se burla mucho de algunos estudiantes'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'fafe619efbfcca24d4b2128c47f6d1ff24e35cd95a17bc29a3e534cb03a4b856'::TEXT, ARRAY[614]::BIGINT[]),
    (534::BIGINT, 'Si quiere pasar en una pura charlatanería todo el semestre metalo con él... No se me entiende bn... Pero los cursos son pasables igual!!'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'ac04e70411cfa87b3802017f438dd4a2984a3742cf2e8c12dac93d380df9ae14'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (534::BIGINT, 'Da la materia útil para salir bien en el examen, pero un poco confusa, si usted entiende lo que él da fijo pasa cagado de la risa, nada mas que mucho chistin.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2015-07-27T00:00:00+00:00'::TIMESTAMPTZ, '3b1e1d7fe7dc95ce2bd50724636ba444c8239d9861da99737c72c26da06df94a'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'a veces se enreda con algunos temas, otros temas los maneja muy bien y los explica fácil.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-20T00:00:00+00:00'::TIMESTAMPTZ, '5b8e085da233420e8caaeaaaca73bbc579464fe2a78ac0fc7a46f446fa085e29'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Explica bien, hace muchos quices lo que ayuda a la nota ya que los más malos no se toman en cuenta, además si uno estudia para estos quices casi no tiene que estudiar para los exámenes. Los ejemplos que dice ayudan ya que uno no los olvida, buen ambiente en clase y ayuda al estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '88e8915a71dc08a49a6ad8c279d20efed9db577af986d98e5c2a55a626e0f177'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Deja mucho quiz y las clases son entretenidas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '8208a8b4eeb2e2c0c4f0329f9e069995ee6d07e091179ddaea26c6f163445c7f'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Se enreda cuando explica, pero es un buen profe. Sus clases son entretenidas y se aprende. Hace bastantes quices para que le vaya bien'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f402ccb6d480bd88d1012953ec1a70bf660df93eed395dc517abef478744855a'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Si se quiere divertir en las clases, adelante, matricule con Juan Carlos. Si usted quiere aprender, simplemente NO LO HAGA. Pésimo explicando, solo puede dar clases con diapositivas de Power Point, se pierde cuando explica la materia, da ejemplos que nada que ver.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '2604bdf4b6aa73e1e5a612a3d499f5fee4ac4d26fb23d6ef720d7a6439ced261'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'No lo recomiendo porque las explicaciones son realmente confusas. Hace bromas que depende de la persona puede sentirse ofendida. Me parece pura vida. Hace quices todas las clases, lo que es bueno. Sus clases me parecieron aburridas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '144e61e8df35487d0d98e7808088994dbb1ee510eea0b2e7626d2ed91117b939'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Se la juega explicando, a veces se enrreda. Al principio es muy pesado luego la clase se vuelve divertida pues es muy bromista aunque a veces pasado. Creo que hay mejores profesores en química pero sí se puede pasar el curso con él además hace quices todas las clases.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '03322def5658af5b5f7ebe19221fc4de4f505063b807380375aede1807c8bc34'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'b02633cbf19eb0e937aadb46374c89d5fc72f23b74e49b43c8dd560f5de6d886'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (534::BIGINT, 'lleve quimica I con el este semestre y espero nunca más volver a llevar algun otro curso, aparte de que no sabe dar bien la clase se enreda solo. pesimos ejemplos, nada acordes y además es totalmente irrespetuoso.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-13T00:00:00+00:00'::TIMESTAMPTZ, '76ce444172e22e2a8be25fb3777624d165ec2b021fe5fa4923a082321608ac99'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Oh! Clases divertidas, al principio parece un repugnante pero es todo pura vida, la materia queda claroy hace muchos quices lo cual ayuda para estudiar y si a uno le va mal no se cuentan todos, es muy justo para calificar.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-11T00:00:00+00:00'::TIMESTAMPTZ, '266af0e69f2bc25c9f209145e5e8b696d47f21cca9779d41bb6eaf7bbe37df19'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'califica justo'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'abd0cd66e2213621258521d583f5f3c3e9218586a9d089e5e80fce4937690470'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Buen profe, divertido, se la juega explicando.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '01bd249725d9194f6fefe625264490ab53b23526ea685c40c4e4901de45a5fb8'::TEXT, ARRAY[568, 573]::BIGINT[]),
    (534::BIGINT, 'Divertidas sus lecciones, pero no se le entiende nada.¡¡¡¡¡'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '8a95d414e921e245152eac3b94c6c119b8d9eb0e3c797e30491d865914f88486'::TEXT, ARRAY[568, 614]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'bb03f0b1904b0589109875503704e98c64e7ecfe05bb83aef501bea49cd83414'::TEXT, ARRAY[567]::BIGINT[]),
    (534::BIGINT, 'OOOOHH!!'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '6314effa327699dd96b15f38523f39baaa9ee76f8dd7c979699c4a20190f5a8c'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Todos dicen que es gracioso pero a mi nunca me da risa y es pésimo explicando, para esa gracia mejor voy a un stand-up comedy y estudio en mi casa, aunque si ayuda cuando uno le reclama puntos y así, y lo deja a uno hacer el quiz si llega tarde'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-23T00:00:00+00:00'::TIMESTAMPTZ, '38e9960c824308cf3d127993a0e7224b274f650d912ba0cfc257e7eff7344d37'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Cuesta entender porque no explica con claridad y se enreda solo. Es muy irrespetuoso además.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-18T00:00:00+00:00'::TIMESTAMPTZ, 'c6af70d27d465d1ca6df2280d0d99271183a349d84d4b10619d8e5534e6b0296'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Excelente profesor sus clases divierten, difícilmente alguien pierda el curso con él, y ayuda mucho. Es muy bueno cuando uno le reclama puntos, solamente que basurea a los que juegan de q saben mucho!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-22T00:00:00+00:00'::TIMESTAMPTZ, '2cd0c029c2398dbbb3c454bf0bccd06de2e4c2a4940156765495af8f5055ae67'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Clases bastante entretenidas, pero explicando no es el mejor'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, '7cc94e4bccd14cbb02edce206a077056ff5633e508f637fbf53edc2de0e8f58c'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (534::BIGINT, 'Es demasiado tuanis. Pero sí, siempre se le enreda lo que explica y hasta se contradice o se le olvida ver alguna materia. Si le pone bastante pasa'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'b69934d9e139fa6f7387326d58066926a1561b2dee62b4fa0c39a17fd099aa20'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'De las clases más entretenidas sin embargo es un poco desordenado, explicando es regular, quices regulares y califica rudo.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'ba034762888b77b55b4ed7d32a90888e4148d3d43d9d84f8ff33550bcb153c1f'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Es probable que sea la clase mas divertida que pueda tener, pero no sabe explicar para nada, y al llegar el examen resulta que muchos temas no los explicó, para nada recomendado'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'e44f8bc89f0c8e5733ba7ad01f02fdd8bf1edf706b8a279289da591730f043f4'::TEXT, ARRAY[567, 613, 568, 614]::BIGINT[]),
    (534::BIGINT, 'No dá con claridad la materia y, en la explicación queda debiendo bastante.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, 'e33390819ffe52df25897c00f7aad9b4c523b0a031d17026f8983bfe2e28b8d0'::TEXT, ARRAY[568]::BIGINT[]),
    (534::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '23bb9a9317119251c22de776370f26be973f5ac1ff810acd48ecb8299363e127'::TEXT, ARRAY[568, 614]::BIGINT[]),
